Negative testing.ejemplo:
# Prueba negativa parametrizada en pytest sobre un endpoint de creación de pedido
@pytest.mark.parametrize("payload", [
    {"qty": -1, "item": "SKU1"},          # cantidad negativa
    {"qty": 999999999999, "item": "SKU1"}, # entero extremo
    {"qty": "1", "item": None},           # tipo erróneo y nulo
    {"qty": 1, "item": "A" * 10000},      # longitud excesiva
])
def test_rejects_invalid_order(client, payload):
    r = client.post("/orders", json=payload)
    assert r.status_code == 422 and "traceback" not in r.text.lower()

