// Ejemplo de fallo que SAST suele omitir y detecta la revisión manual (BOLA / IDOR):
@GetMapping("/api/reports/{reportId}")
public Report getReport(@PathVariable UUID reportId, @AuthenticationPrincipal User user) {
    // SAST ve consultas parametrizadas limpias y @AuthenticationPrincipal presente,
    // pero la revisión manual detecta que no se valida report.getTenantId().equals(user.getTenantId()).
    return reportRepository.findById(reportId).orElseThrow();
}
